begin;
create function public.assert_revision_lease(p_id uuid,p_worker uuid,p_attempt integer) returns public.jobs language plpgsql security definer set search_path='' as $$declare j public.jobs;begin select * into j from public.jobs where id=p_id and status='running' and lease_token=p_worker and attempt_count=p_attempt and lease_expires_at>clock_timestamp() for update;if not found then raise exception 'JOB_LEASE_LOST';end if;if j.kind<>'delete_account' and not exists(select 1 from public.profiles where user_id=j.user_id and account_state='active') then raise exception 'ACCOUNT_DISABLED';end if;return j;end $$;
create function public.put_revision_artifact(p_id uuid,p_worker uuid,p_attempt integer,p_index integer,p_data jsonb) returns jsonb language plpgsql security definer set search_path='' as $$declare j public.jobs;d jsonb;begin j:=public.assert_revision_lease(p_id,p_worker,p_attempt);if p_index is null or p_index not between 0 and 500 or p_data is null or jsonb_typeof(p_data)<>'object' then raise exception 'INVALID_ARTIFACT';end if;insert into public.job_artifacts(job_id,user_id,item_index,data) values(j.id,j.user_id,p_index,p_data) on conflict(job_id,item_index) do nothing;select data into d from public.job_artifacts where job_id=j.id and item_index=p_index;return d;end $$;
create function public.reserve_ai_request(p_user uuid,p_user_limit integer,p_global_limit integer) returns boolean language plpgsql security definer set search_path='' as $$declare n integer;begin if p_global_limit is null or p_global_limit not between 1 and 10000 or p_user_limit is null or p_user_limit not between 1 and 1000 then raise exception 'INVALID_AI_LIMIT';end if;if not public.consume_revision_usage(p_user,'ai_requests',p_user_limit) then return false;end if;insert into public.ai_request_days values((now() at time zone 'UTC')::date,1) on conflict(day) do update set used=public.ai_request_days.used+1 where public.ai_request_days.used<p_global_limit returning used into n;return found;end $$;
create function public.enqueue_revision_job(p_user uuid,p_kind text,p_payload jsonb,p_event uuid) returns uuid language plpgsql security definer set search_path='' as $$declare jid uuid;begin
if p_user is null or p_event is null or not exists(select 1 from public.profiles where user_id=p_user and account_state='active') then raise exception 'ACCOUNT_DISABLED';end if;
if p_kind not in('generate_question','process_document','mark_attempt') or p_payload is null or jsonb_typeof(p_payload)<>'object' then raise exception 'INVALID_JOB';end if;
select id into jid from public.jobs where user_id=p_user and idempotency_key=p_kind||':'||p_event::text;if found then return jid;end if;
if p_kind='process_document' and not exists(select 1 from public.documents where id=(p_payload->>'document_id')::uuid and user_id=p_user and status in('awaiting_upload','queued','review')) then raise exception 'DOCUMENT_NOT_AVAILABLE';end if;
if p_kind='mark_attempt' and not exists(select 1 from public.attempts a left join public.mock_exams m on m.id=a.mock_id where a.id=(p_payload->>'attempt_id')::uuid and a.user_id=p_user and a.status='submitted' and(a.mock_id is null or m.status in('submitted','marking','marked','review'))) then raise exception 'ANSWER_NOT_SUBMITTED';end if;
if p_kind='generate_question' and not public.consume_revision_usage(p_user,'generation_jobs',20) then raise exception 'GENERATION_LIMIT';end if;
insert into public.jobs(user_id,kind,payload,idempotency_key) values(p_user,p_kind,p_payload,p_kind||':'||p_event::text) returning id into jid;
if p_kind='process_document' then update public.documents set status='queued' where id=(p_payload->>'document_id')::uuid and user_id=p_user;end if;return jid;end $$;
create function public.create_revision_assessment(p_user uuid,p_qualification text,p_blueprint uuid,p_event uuid) returns uuid language plpgsql security definer set search_path='' as $$declare sid uuid;mid uuid;b record;programme text;begin
select programme_key into programme from public.profiles where user_id=p_user and account_state='active';if programme is null or not exists(select 1 from public.programme_qualifications where programme_key=programme and qualification_code=p_qualification) then raise exception 'QUALIFICATION_OUTSIDE_LEARNER_PROGRAMME';end if;
select(output->>'set_id')::uuid into sid from public.jobs where user_id=p_user and idempotency_key='assessment:'||p_event::text;if found then return sid;end if;
if not public.consume_revision_usage(p_user,'mock_sets',3) then raise exception 'MOCK_LIMIT';end if;
if not exists(select 1 from public.qualification_papers where qualification_code=p_qualification and(p_blueprint is null or blueprint_id=p_blueprint)) then raise exception 'INVALID_BLUEPRINT';end if;
insert into public.assessment_sets(user_id,qualification_code) values(p_user,p_qualification) returning id into sid;
for b in select bp.* from public.qualification_papers qp join public.paper_blueprints bp on bp.id=qp.blueprint_id where qp.qualification_code=p_qualification and(p_blueprint is null or bp.id=p_blueprint) loop
insert into public.mock_exams(user_id,subject_code,blueprint_id,qualification_code,assessment_set_id) values(p_user,b.subject_code,b.id,p_qualification,sid) returning id into mid;
insert into public.jobs(user_id,kind,payload,idempotency_key) values(p_user,'build_mock',jsonb_build_object('mock_id',mid,'programme',programme,'qualification',p_qualification),'mock:'||mid::text);
end loop;
insert into public.jobs(user_id,kind,status,payload,output,idempotency_key) values(p_user,'build_mock','succeeded','{}',jsonb_build_object('set_id',sid),'assessment:'||p_event::text);return sid;end $$;
create function public.save_revision_answer_v2(p_id uuid,p_user uuid,p_answer text,p_version integer) returns public.attempts language plpgsql security definer set search_path='' as $$declare a public.attempts;m public.mock_exams;begin
if not exists(select 1 from public.profiles where user_id=p_user and account_state='active') then raise exception 'ACCOUNT_DISABLED';end if;select * into a from public.attempts where id=p_id and user_id=p_user;if not found then raise exception 'ATTEMPT_NOT_FOUND';end if;
if a.mock_id is not null then select * into m from public.mock_exams where id=a.mock_id for update;if m.status<>'active' or clock_timestamp()>=m.deadline then raise exception 'EXAM_CLOSED';end if;end if;
select * into a from public.attempts where id=p_id and user_id=p_user for update;if p_version is null or a.answer_version<>p_version then raise exception 'ANSWER_VERSION_CONFLICT';end if;a:=public.save_revision_answer(p_id,p_user,p_answer);update public.attempts set answer_version=answer_version+1 where id=p_id returning * into a;perform public.record_study_activity(p_user);return a;end $$;
create function public.submit_revision_practice(p_id uuid,p_user uuid) returns uuid language plpgsql security definer set search_path='' as $$declare a public.attempts;jid uuid;begin
select * into a from public.attempts where id=p_id and user_id=p_user for update;if not found or a.mock_id is not null then raise exception 'ATTEMPT_NOT_AVAILABLE';end if;if a.status='draft' then update public.attempts set status='submitted',submitted_at=clock_timestamp() where id=p_id;end if;
insert into public.jobs(user_id,kind,payload,idempotency_key) values(p_user,'mark_attempt',jsonb_build_object('attempt_id',p_id),'mark:'||p_id::text) on conflict(user_id,idempotency_key) do nothing;select id into jid from public.jobs where user_id=p_user and idempotency_key='mark:'||p_id::text;return jid;end $$;
create function public.publish_document_job(p_id uuid,p_worker uuid,p_attempt integer,p_extraction jsonb) returns jsonb language plpgsql security definer set search_path='' as $$declare j public.jobs;did uuid;p jsonb;q jsonb;review boolean:=false;outcome jsonb;begin
j:=public.assert_revision_lease(p_id,p_worker,p_attempt);if j.kind<>'process_document' then raise exception 'INVALID_JOB';end if;did:=(j.payload->>'document_id')::uuid;
if not exists(select 1 from public.documents where id=did and user_id=j.user_id and status in('queued','processing','review')) then raise exception 'DOCUMENT_NOT_AVAILABLE';end if;
if jsonb_typeof(p_extraction->'pages')<>'array' or jsonb_array_length(p_extraction->'pages')<>(p_extraction->>'page_count')::integer then raise exception 'INVALID_EXTRACTION';end if;
delete from public.extracted_questions where document_id=did and user_id=j.user_id;delete from public.document_pages where document_id=did and user_id=j.user_id;
for p in select value from jsonb_array_elements(p_extraction->'pages') loop review:=review or(p->>'confidence')::numeric<.95 or jsonb_array_length(p->'uncertainties')>0;insert into public.document_pages(document_id,user_id,page_number,width,height,text_content,blocks,ocr_confidence,needs_review) values(did,j.user_id,(p->>'number')::integer,1,1,p->>'text','[]',(p->>'confidence')::numeric,(p->>'confidence')::numeric<.95 or jsonb_array_length(p->'uncertainties')>0);end loop;
for q in select value from jsonb_array_elements(p_extraction->'items') loop review:=review or(q->>'confidence')::numeric<.95;insert into public.extracted_questions(document_id,user_id,subject_code,question_label,page_number,prompt,marks,command_word,question_type,required_knowledge,source_regions,structured_content,needs_review,ocr_confidence) select did,j.user_id,d.subject_code,q->>'label',(q->>'page')::integer,q->>'prompt',(q->>'marks')::integer,q->>'command',q->>'format',q->'knowledge','[]',q->'content',true,(q->>'confidence')::numeric from public.documents d where d.id=did;end loop;
update public.documents set status='review',page_count=(p_extraction->>'page_count')::integer,extraction_summary=p_extraction->>'summary' where id=did and user_id=j.user_id;
outcome:=jsonb_build_object('document_id',did,'items',jsonb_array_length(p_extraction->'items'),'review_required',true);perform public.finish_revision_job(j.id,p_worker,p_attempt,outcome,'review');return outcome;end $$;
create function public.review_extracted_item(p_id uuid,p_user uuid,p_prompt text,p_marks integer) returns boolean language plpgsql security definer set search_path='' as $$declare did uuid;begin
if p_prompt is null or length(trim(p_prompt)) not between 1 and 20000 or p_marks is null or p_marks not between 1 and 100 then raise exception 'INVALID_REVIEW';end if;
update public.extracted_questions set prompt=trim(p_prompt),marks=p_marks,needs_review=false,reviewed_at=clock_timestamp() where id=p_id and user_id=p_user returning document_id into did;if not found then raise exception 'ITEM_NOT_FOUND';end if;
if not exists(select 1 from public.extracted_questions where document_id=did and needs_review) then update public.documents set status='ready' where id=did and user_id=p_user;end if;return true;end $$;
create or replace function public.check_question_integrity() returns trigger language plpgsql security definer set search_path='' as $$declare qid uuid;q public.generated_questions;n integer;total integer;v jsonb;begin
if TG_TABLE_NAME='generated_questions' then qid:=coalesce(new.id,old.id);else qid:=coalesce(new.question_id,old.question_id);end if;select * into q from public.generated_questions where id=qid;if not found or q.validation_status<>'validated' then return null;end if;
if not exists(select 1 from public.topics t join public.specification_versions s on s.id=t.specification_id where t.id=q.topic_id and t.subject_code=q.subject_code and t.kind='objective' and t.verified and s.checked_at is not null) then raise exception 'TOPIC_NOT_VERIFIED_OBJECTIVE';end if;
select count(*),coalesce(sum(marks),0) into n,total from public.mark_criteria where question_id=qid;if n=0 or total<>q.marks then raise exception 'CRITERION_TOTAL_MISMATCH';end if;select verification into v from public.question_solutions where question_id=qid;
if v is null or v->>'scientific_status' is distinct from 'pass' or v->>'mark_scheme_status' is distinct from 'pass' or v->>'model' is null or v->>'generator_model' is null or v->>'model'=v->>'generator_model' then raise exception 'QUESTION_VERIFICATION_MISSING';end if;
if q.origin='original_ai' and v->>'originality_status' is distinct from 'pass' then raise exception 'QUESTION_ORIGINALITY_NOT_PASSED';end if;
if q.origin='private_import' and(v->>'originality_status' is distinct from 'not_applicable_private_import' or not exists(select 1 from public.extracted_questions e join public.documents d on d.id=e.document_id where e.id=q.source_extracted_id and e.user_id=q.user_id and e.subject_code=q.subject_code and not e.needs_review and d.rights_attested_at is not null)) then raise exception 'PRIVATE_IMPORT_NOT_AUTHORIZED';end if;return null;end $$;
create function public.publish_question_job(p_id uuid,p_worker uuid,p_attempt integer,p_count integer) returns jsonb language plpgsql security definer set search_path='' as $$declare j public.jobs;a record;p jsonb;q jsonb;v jsonb;c jsonb;qid uuid;mid uuid;cid uuid;ids jsonb:='[]';n integer:=0;purpose text;source_id uuid;outcome jsonb;begin
j:=public.assert_revision_lease(p_id,p_worker,p_attempt);if j.kind not in('generate_question','build_mock') or p_count not between 1 and 200 then raise exception 'INVALID_JOB';end if;purpose:=coalesce(j.payload->>'purpose','practice');source_id:=(j.payload->>'extracted_id')::uuid;if j.kind='build_mock' then mid:=(j.payload->>'mock_id')::uuid;if not exists(select 1 from public.mock_exams where id=mid and user_id=j.user_id and status='building') then raise exception 'MOCK_NOT_AVAILABLE';end if;end if;
if(select count(*) from public.job_artifacts where job_id=j.id and item_index between 0 and p_count-1)<>p_count then raise exception 'INCOMPLETE_QUESTION_BATCH';end if;
for a in select * from public.job_artifacts where job_id=j.id and item_index between 0 and p_count-1 order by item_index loop
p:=a.data->'packet';q:=p->'question';v:=a.data->'verification';
insert into public.generated_questions(user_id,subject_code,topic_id,prompt,structured_content,choices,marks,difficulty,format,command_word,examination_style,content_hash,origin,source_extracted_id) values(j.user_id,q->>'subject_code',(q->>'topic_id')::uuid,q->>'prompt',q->'structured_content',q->'choices',(q->>'marks')::integer,q->>'difficulty',q->>'format',q->>'command_word','International GCSE linear',a.data->>'content_hash',case when source_id is null then 'original_ai' else 'private_import' end,source_id) returning id into qid;
insert into public.question_solutions(question_id,model_answer,correct_choice_id,examiner_explanation,common_mistakes,numerical_checks,verification) values(qid,q->>'model_answer',q->>'correct_choice_id',q->>'examiner_explanation',array(select jsonb_array_elements_text(q->'common_mistakes')),q->'numerical_checks',v);
for c in select value from jsonb_array_elements(q->'criteria') loop insert into public.mark_criteria(question_id,criterion_key,description,marks,allow_ecf,ecf_rule,acceptable_alternatives) values(qid,c->>'key',c->>'description',(c->>'marks')::integer,(c->>'allow_ecf')::boolean,c->>'ecf_rule',array(select jsonb_array_elements_text(c->'acceptable_alternatives')));end loop;
insert into public.question_visuals values(qid,p->'visuals');update public.generated_questions set validation_status='validated' where id=qid;
if mid is not null then insert into public.mock_exam_questions values(mid,j.user_id,q->>'subject_code',qid,a.item_index+1,(a.item_index+1)::text);end if;
if purpose='cards' then insert into public.flashcards(user_id,subject_code,topic_id,front,back,origin,validation_status) values(j.user_id,q->>'subject_code',(q->>'topic_id')::uuid,q->>'prompt',q->>'model_answer','original_ai','validated') returning id into cid;insert into public.flashcard_schedule(card_id,user_id) values(cid,j.user_id);end if;
ids:=ids||jsonb_build_array(qid);n:=n+1;end loop;
if mid is not null then update public.mock_exams set status='ready' where id=mid;end if;outcome:=jsonb_build_object('question_ids',ids,'count',n,'mock_id',mid,'purpose',purpose);perform public.finish_revision_job(j.id,p_worker,p_attempt,outcome);return outcome;end $$;
create function public.publish_marking_job(p_id uuid,p_worker uuid,p_attempt integer,p_mark jsonb,p_input_hash text,p_model text) returns jsonb language plpgsql security definer set search_path='' as $$declare j public.jobs;a public.attempts;rid uuid;award jsonb;cid uuid;outcome jsonb;begin
j:=public.assert_revision_lease(p_id,p_worker,p_attempt);if j.kind<>'mark_attempt' then raise exception 'INVALID_JOB';end if;select * into a from public.attempts where id=(j.payload->>'attempt_id')::uuid and user_id=j.user_id for update;if not found or a.status not in('submitted','marking') then raise exception 'ANSWER_NOT_SUBMITTED';end if;
insert into public.marking_runs(attempt_id,user_id,question_id,earned_marks,available_marks,confidence,feedback,misconceptions,model_id,input_sha256,verification) values(a.id,a.user_id,a.question_id,(p_mark->>'earned_marks')::integer,(p_mark->>'available_marks')::integer,(p_mark->>'confidence')::numeric,p_mark->>'feedback',array(select jsonb_array_elements_text(p_mark->'misconceptions')),p_model,p_input_hash,'{"status":"pass"}') returning id into rid;
for award in select value from jsonb_array_elements(p_mark->'awards') loop select id into cid from public.mark_criteria where question_id=a.question_id and criterion_key=award->>'criterion_key';if cid is null then raise exception 'UNKNOWN_CRITERION';end if;insert into public.criterion_awards values(rid,cid,a.question_id,(award->>'marks')::integer,award->>'evidence',(award->>'ecf')::boolean,award->>'explanation');end loop;
update public.marking_runs set status='validated' where id=rid;update public.attempts set status='marked',accepted_marking_id=rid where id=a.id;
if a.mock_id is not null and not exists(select 1 from public.attempts where mock_id=a.mock_id and status<>'marked') then update public.mock_exams set status='marked' where id=a.mock_id;end if;
outcome:=jsonb_build_object('attempt_id',a.id,'run_id',rid);perform public.finish_revision_job(j.id,p_worker,p_attempt,outcome);return outcome;end $$;
create function public.sweep_expired_mocks() returns integer language plpgsql security definer set search_path='' as $$declare m record;n integer:=0;begin for m in select id,user_id from public.mock_exams where status='active' and deadline<=clock_timestamp() for update skip locked loop perform public.submit_revision_mock(m.id,m.user_id);n:=n+1;end loop;return n;end $$;
create function public.queue_revision_erasure(p_user uuid) returns uuid language plpgsql security definer set search_path='' as $$declare jid uuid;after_time timestamptz;begin
select id into jid from public.jobs where user_id=p_user and kind='delete_account';if found then return jid;end if;update public.profiles set account_state='deleting',share_study_stats=false,friend_chat_enabled=false where user_id=p_user;if not found then raise exception 'ACCOUNT_NOT_FOUND';end if;
update public.jobs set status='cancelled',lease_token=null,lease_expires_at=null where user_id=p_user and status in('queued','running');select greatest(clock_timestamp(),coalesce(max(upload_expires_at),clock_timestamp()))+interval '5 minutes' into after_time from public.documents where user_id=p_user;
insert into public.jobs(user_id,kind,payload,idempotency_key,run_after) values(p_user,'delete_account',jsonb_build_object('not_before',after_time),'erase:'||p_user::text,after_time) returning id into jid;return jid;end $$;
create function public.purge_revision_report_content(p_user uuid) returns void language sql security definer set search_path='' as $$delete from public.chat_reports where reporter_id=p_user or message_id in(select id from public.chat_messages where sender_id=p_user)$$;
do $$declare f record;begin for f in select oid::regprocedure sig from pg_proc where pronamespace='public'::regnamespace and proname in('assert_revision_lease','put_revision_artifact','reserve_ai_request','enqueue_revision_job','create_revision_assessment','save_revision_answer_v2','submit_revision_practice','publish_document_job','review_extracted_item','publish_question_job','publish_marking_job','sweep_expired_mocks','queue_revision_erasure','purge_revision_report_content') loop execute format('revoke all on function %s from public,anon,authenticated',f.sig);execute format('grant execute on function %s to service_role',f.sig);end loop;end $$;
commit;
